#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The console-only steps of the public launch's safety work (issue #71): the report address saved for the stack; the
# deploy; a check that SES can send as the address (its domain verified, or the address verified on its own, which
# needs a click on SES's link); a test report mail; and, when the maintainer decides, moderation on and the AI services
# opt-out.
#
#   infra/scripts/safety-wizard.sh                  # from the start
#   WIZARD_FROM=3 infra/scripts/safety-wizard.sh    # resume at stage 3 (e.g. after the deploy)
#
# Run infra/scripts/accounts-wizard.sh and circles-wizard.sh first (every deploy needs their values). The report
# address is the sender and the only recipient. A verified identity may mail itself even from the SES sandbox, so
# production access is needed only to send reports elsewhere (stage 5 checks it; the shared account has it already).

run_wizard() {

TOTAL_STAGES=6
WIZARD_FROM="${WIZARD_FROM:-1}"

for tool in aws jq uv; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required: brew install %s\n' "$tool" "$tool" >&2; exit 1; }
done

INFRA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
mkdir -p "$HOME/keys"
ENV_FILE="$HOME/keys/birdjournal.env"
AWS_REGION="us-west-2"
export AWS_PROFILE="${AWS_PROFILE:-lsvr-admin}"

AWS_ACCOUNT=$(aws sts get-caller-identity --query Account --output text 2>/dev/null) || {
  printf 'AWS profile %s has no working credentials (aws sso login --profile %s?). Fix that, then re-run.\n' \
    "$AWS_PROFILE" "$AWS_PROFILE" >&2
  exit 1
}

begin() {
  if (( _STAGE_INDEX + 1 < WIZARD_FROM )); then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; fi
  stage "$1"
}

saved() { [[ -f "$ENV_FILE" ]] && (source "$ENV_FILE" && printf '%s' "${!1:-}"); }

report_email() { local value; value=$(saved REPORT_EMAIL); [[ -n "$value" ]] && printf '%s' "$value" || saved BUDGET_ALERT_EMAIL; }

identity_status() {
  aws sesv2 get-email-identity --region "$AWS_REGION" --email-identity "$1" \
    --query 'VerificationStatus' --output text 2>/dev/null || printf 'MISSING'
}

banner "BirdJournal: reports by email, moderation and account deletion"

if begin "The report address"; then
  say "Reports of finds and members are stored and emailed to you through Amazon SES."
  say "The address is kept out of the public repo, in $ENV_FILE, like the budget's."
  current=$(report_email || true)
  [[ -n "$current" ]] && note "Now: $current"
  if [[ -z "$current" ]] || ! confirm "Keep $current?"; then
    until ask REPORT_EMAIL "Report address:" && [[ "$REPORT_EMAIL" == *@*.* ]]; do warn "That isn't an email address."; done
    write_env REPORT_EMAIL "$REPORT_EMAIL"
  fi
  pause
fi

if begin "Deploy: the SES identity and the API's new permissions"; then
  say "infra/scripts/deploy.sh runs the template tests, checks the shared us-west-2 bootstrap (it never"
  say "bootstraps), and deploys the API's rights to send as $(report_email) or its domain, Rekognition (used"
  say "only once moderation is on), AdminDeleteUser on the user pool and the Apple key's secret."
  if confirm "Deploy BirdJournal to $AWS_ACCOUNT / $AWS_REGION now?"; then
    REPORT_EMAIL="$(report_email)" "$INFRA_DIR/scripts/deploy.sh"
  else
    SKIPPED+=("deploy: REPORT_EMAIL=... infra/scripts/deploy.sh, then WIZARD_FROM=3 infra/scripts/safety-wizard.sh")
    finish; exit 0
  fi
  pause
fi

if begin "SES: can it send as the report address?"; then
  address=$(report_email)
  domain="${address#*@}"
  if [[ "$(identity_status "$domain")" == "SUCCESS" ]]; then
    printf '  %s✓%s the domain %s is verified in SES: it covers %s\n' "$GREEN" "$RESET" "$domain" "$address"
  elif [[ "$(identity_status "$address")" == "SUCCESS" ]]; then
    printf '  %s✓%s %s is verified in SES\n' "$GREEN" "$RESET" "$address"
  else
    say "Neither $domain nor $address is a verified SES identity in $AWS_REGION."
    if confirm "Verify $address on its own now (SES emails it a link)?"; then
      aws sesv2 create-email-identity --region "$AWS_REGION" --email-identity "$address" \
        --tags Key=project,Value=birdjournal >/dev/null 2>&1 \
        || aws ses verify-email-identity --region "$AWS_REGION" --email-address "$address"
      step "Open the email \"Amazon Web Services – Email Address Verification Request in region US West (Oregon)\"."
      step "Click the link inside within 24 hours."
      pause "Press Enter once you've clicked it."
      status=$(identity_status "$address")
      if [[ "$status" != "SUCCESS" ]]; then
        warn "SES says $status. Click the link, then resume with WIZARD_FROM=3."
        finish; exit 1
      fi
      printf '  %s✓%s %s is verified\n' "$GREEN" "$RESET" "$address"
    else
      SKIPPED+=("SES identity for $address: WIZARD_FROM=3 infra/scripts/safety-wizard.sh")
    fi
  fi
  pause
fi

if begin "Check: a test report mail"; then
  address=$(report_email)
  if confirm "Send a test report mail to $address through SES now?"; then
    if aws sesv2 send-email --region "$AWS_REGION" --from-email-address "$address" \
        --destination "ToAddresses=$address" \
        --content "Simple={Subject={Data='BirdJournal report: a test from the safety wizard'},Body={Text={Data='Reports from the app will look like this, with what was reported and by whom.'}}}" \
        >/dev/null; then
      printf '  %s✓%s SES took it: check %s (and its spam folder).\n' "$GREEN" "$RESET" "$address"
    else
      warn "SES refused it: is the identity verified (WIZARD_FROM=3)?"
    fi
  fi
  pause
fi

if begin "Optional: reports to another address (SES production access)"; then
  production=$(aws sesv2 get-account --region "$AWS_REGION" --query 'ProductionAccessEnabled' --output text 2>/dev/null || true)
  if [[ "$production" == "True" ]]; then
    printf '  %s✓%s SES production access is on in %s: reports could go to any address.\n' "$GREEN" "$RESET" "$AWS_REGION"
  else
    say "In the sandbox SES only mails verified addresses. The report address mails itself, so this is"
    say "needed only to send reports somewhere unverified. Skip it otherwise."
  fi
  if [[ "$production" != "True" ]] && confirm "Request production access now?"; then
    open_url "https://us-west-2.console.aws.amazon.com/ses/home?region=us-west-2#/account"
    step "Request production access. Mail type: Transactional. Website: https://featherguild.matthewcelia.com"
    step "Use case: 'Moderation reports from the Bird Journal app, sent only to the maintainer, a few a week.'"
    note "AWS answers within a day; nothing in the stack changes either way."
  fi
  pause
fi

if begin "When you launch publicly: moderation on, and the AI services opt-out"; then
  say "Moderation (Rekognition on shared photos) is off: \"moderation\": \"off\""
  say "in infra/cdk.json. For the public launch set it to \"on\" and deploy; nothing else changes."
  say "AWS may keep content Rekognition processes to improve the service unless the organization opts out."
  say "The opt-out is an AWS Organizations 'AI services opt-out policy' on the management (payer) account."
  if confirm "Open the Organizations policies page now?"; then
    open_url "https://us-east-1.console.aws.amazon.com/organizations/v2/home/policies/ai-services-opt-out-policy"
    step "Enable the policy type, then create a policy opting out of all services (\"default\": optOut) and"
    step "attach it to the root or to account $AWS_ACCOUNT."
    note "Needs the payer account; if this profile isn't it, ask the account's owner."
  fi
  pause
fi

finish
note "on a device: Settings → Account → Delete account removes the account (the app signs out), and the"
note "next sign-in starts a new, empty account. For Sign in with Apple, Settings → Apple ID → Sign in with"
note "Apple no longer lists Bird Journal."
printf '\n'
}

run_wizard "$@"; exit
